// El modelo se captura de la URL path: /crud/:model
const modelName = $node["WebhookCRUD"].json.params.model;
const requestBody = $node["WebhookCRUD"].json.body;
// Capturamos los headers aquí para pasarlos adelante
const headers = $node["WebhookCRUD"].json.headers;

if (!modelName) {
  throw new Error('Parámetro faltante en URL: se requiere el nombre del modelo');
}

return [{
    json: {
        model_name: modelName,
        headers: headers, // <-- Agregamos esto
        ...requestBody 
    }
}];

const modelConfig = $node["Get Model Config"].json;
const webhookBody = $node["WebhookCRUD"].json.body || {};
const operation = (webhookBody.operation || "").toLowerCase();
const bodyFields = webhookBody.fields || {};

// SOLO validamos campos requeridos si es INSERT o UPDATE
if (["insert", "update"].includes(operation)) {
    if (modelConfig.schema_json) {
        const schema = modelConfig.schema_json;
        Object.keys(schema).forEach(field => {
            if (schema[field].required === true) {
                if (bodyFields[field] === undefined || bodyFields[field] === null) {
                    // throw new Error(`Campo requerido faltante: ${field}`);
                    return {
                      json: {
                        error: true,
                        status: 400,
                        message: `Campo requerido faltante: ${field}`,
                        code: "SCHEMA_VALIDATION"
                      }
                    };
                }
            }
        });
    }
}

return { json: { ...modelConfig, validated: true } };

