// 1. Acceder al contenido de la IA (Viene del nodo anterior)
const aiOutput = $json.output?.[0]?.content?.[0]?.text?.message;

if (!aiOutput) {
  throw new Error("No se encontró contenido en la respuesta de la IA.");
}

try {
  // 2. Parsear el JSON generado por la IA
  const cleanJson = JSON.parse(aiOutput);

  // 3. Obtener las columnas reales (Usamos $(...).all() para obtener los datos del nodo Get)
  // El nodo 'Aggregate' unifica todo, pero 'Get' tiene la lista original de columnas.
  const getOutput = $("Get").all();
  const realColumns = getOutput.map(item => item.json.column_name);

  if (realColumns.length === 0) {
    throw new Error("No se pudieron recuperar las columnas del nodo 'Get'.");
  }

  let finalPK = cleanJson.primary_key;

  // 4. VALIDACIÓN DE LA PRIMARY KEY
  if (!realColumns.includes(finalPK)) {
    // Si la IA inventó algo, buscamos una real
    const backupPK = realColumns.find(c => c.toLowerCase() === 'id' || c.toLowerCase().endsWith('_id')) 
                     || (cleanJson.table_name === 'users' && realColumns.includes('email') ? 'email' : null)
                     || realColumns[0];

    finalPK = backupPK;
  }

  // 5. Retornar el objeto limpio para el INSERT
  return [{
    json: {
      ...cleanJson,
      primary_key: finalPK,
      allowed_fields: realColumns, // Forzamos las columnas reales detectadas
      schema_json: typeof cleanJson.schema_json === 'string' ? JSON.parse(cleanJson.schema_json) : cleanJson.schema_json,
      hooks: cleanJson.hooks || { pre: [], post: [] }
    }
  }];

} catch (e) {
  throw new Error("Error al procesar configuración de IA: " + e.message);
}

let role = null;
const modelName = $("Get Model Name").first().json.model_name;

// Intentamos obtener el token de forma segura
try {
  const verifyTokenNode = $("Verify Token").first();
  if (verifyTokenNode && verifyTokenNode.json.status === "success") {
    role = verifyTokenNode.json.data?.user?.role;
  }
} catch (error) {
  // Si entra aquí es porque 'Verify Token' no se ejecutó (camino público)
  // No hacemos nada, dejamos que role siga siendo null para validarlo abajo
}

// Lógica de asignación
if (!role && modelName === 'companys') {
  role = 'CUSTOMER'; 
}

if (!role) {
  return [{
    json: {
      error: true,
      status: 401,
      message: "Acceso denegado: Se requiere autenticación o modelo no público.",
      code: "NO_ROLE"
    }
  }];
}

return [{
  json: {
    user: {
      role: role.toUpperCase()
    }
  }
}];

// 1. Obtener datos de entrada
const authContext = $json;

// 2. Acceder al Webhook original de forma segura (usando .first() para saltar ramas)
const webhookData = $('WebhookCRUD').first().json;
const body = webhookData.body || {};

// Capturamos 'action' o 'operation' (Angular mandó 'action': 'list')
const operationRaw = (body.action || body.operation || "").toLowerCase();

// VALIDACIÓN DE OPERACIÓN FALTANTE
if (!operationRaw) {
  return [{
    json: {
      error: true,
      status: 400,
      message: "No se especificó ninguna acción u operación (list, insert, etc.)",
      code: "MISSING_OPERATION"
    }
  }];
}

const userRole = authContext.user?.role;
if (!userRole) {
  return [{
    json: {
      error: true,
      status: 401,
      message: "Acceso Denegado: Rol de usuario no definido.",
      code: "AUTH_ERROR"
    }
  }];
}

// 3. Mapeo de operaciones
const opMapping = { 
    'list': 'getall',
    'getall': 'getall',
    'getone': 'getone',
    'insert': 'insert',
    'update': 'update',
    'delete': 'delete',
    'select': 'getall',
    'call_sp': 'call_sp'
};

const opToValidate = opMapping[operationRaw] || 'getall';

// Mapeo para revisar permisos en DB (la DB sí usa select/insert/update/delete)
const opForSecurity = ['getall', 'getone'].includes(opToValidate) ? 'select' : opToValidate;

// 4. Obtener la configuración del modelo
const modelConfig = $('Schema Validate').first().json;

// 5. Verificación de permisos de Operación
const allowedOps = Array.isArray(modelConfig.allowed_ops) ? modelConfig.allowed_ops : [];
const isOpAllowed = allowedOps.map(op => op.toLowerCase()).includes(opForSecurity);

if (!isOpAllowed) {
  return [{ json: { error: true, status: 403, message: `Operación no permitida para este modelo.` } }];
}

// 6. Verificación de Rol contra la DB
const roleKey = `allowed_roles_${opForSecurity}`;

const allowedRolesStr = modelConfig[roleKey] || ""; // Si no existe la columna, queda vacío
if (!allowedRolesStr) {
    return [{
        json: {
            error: true,
            status: 500,
            message: `Configuración de seguridad faltante: No se encontró la columna ${roleKey} en la tabla crud_models.`,
            code: "CONFIG_ERROR"
        }
    }];
}

const allowedRolesList = allowedRolesStr.split(',').map(r => r.trim().toUpperCase());
if (!allowedRolesList.includes(userRole.toUpperCase())) {
  return [{
    json: {
      error: true,
      status: 403,
      message: `Prohibido: El rol '${userRole}' no tiene permiso para '${operationRaw.toUpperCase()}'`,
      code: "SECURITY_VALIDATION"
    }
  }];
}

// TODO OK: Retornar configuración con bandera de éxito
return [{
  json: {
    ...modelConfig,
    user_role: userRole,
    operation: opToValidate,
    error: false
  }
}];

const crypto = require('crypto');

// Capturamos los datos directamente de los nodos anteriores
const config = $('Security Validation').first().json;
const webhookData = $('WebhookCRUD').first().json; // Obtenemos el payload completo
const body = webhookData.body || {};
const headers = webhookData.headers || {};
const operation = (config.operation || '').toLowerCase();
const table = config.table_name;

// 🚀 FIX: Soportar "filter" en singular y aislar el payload
// Hacemos una copia profunda (JSON.parse) para no mutar el objeto original
let fields = body.filter || body.filters || body.fields || JSON.parse(JSON.stringify(body));

// 🛡️ SECURITY PATCH: Aislamiento Multi-Tenant (Zero-Trust)
// Solo inyectamos tenant_id si el modelo realmente tiene esa columna
const tenantIdHeader = headers['x-tenant-id'];
const modelHasTenantId = (config.allowed_fields || []).includes('tenant_id');
if (tenantIdHeader && modelHasTenantId) {
    fields['tenant_id'] = tenantIdHeader;
}
const joins = config.joins || [];
const buildJoins = () => {
    if (!joins.length) return '';
    return joins.map(j => {
        const myCol = j.own_col || j.localField;
        const otherCol = j.foreign_col || j.foreignField || 'id';
        return ` LEFT JOIN ${j.table} ON ${table}.${myCol} = ${j.table}.${otherCol}`;
    }).join(' ');
};

const buildSelectFields = () => {
    if (!joins.length) return `${table}.*`;
    let select = `${table}.*`;
    joins.forEach(j => { select += `, row_to_json(${j.table}.*) as ${j.table}_data`; });
    return select;
};

const processValue = (key, value) => {
    if (key === 'password' && value) return crypto.createHash('sha256').update(value).digest('hex');
    return value;
};

// Sanitización de paginación
const sanitizePaginationParams = (limitInput, offsetInput) => {
    let limit = 1000;
    let offset = 0;
    if (limitInput) {
        const parsedLimit = parseInt(limitInput, 10);
        if (!isNaN(parsedLimit) && parsedLimit > 0) limit = Math.min(parsedLimit, 2000);
    }
    if (offsetInput) {
        const parsedOffset = parseInt(offsetInput, 10);
        if (!isNaN(parsedOffset) && parsedOffset >= 0) offset = parsedOffset;
    }
    return { limit, offset };
};

let query = '';
let values = [];

switch (operation) {
    case 'insert': {
        const allowedFields = config.allowed_fields || [];
        const insertFields = [];
        const placeholders = [];
        let paramIndex = 1;

        Object.entries(fields).forEach(([key, value]) => {
            if (allowedFields.includes(key)) {
                insertFields.push(key);
                placeholders.push(`$${paramIndex++}`);
                values.push(processValue(key, value));
            }
        });

        if (insertFields.length === 0) throw new Error("No hay campos válidos para insertar.");

        // Obtener la PK configurada (soporta simples y compuestas separadas por coma)
        const primaryKeyStr = config.primary_key || 'id';
        const pkList = primaryKeyStr.split(',').map(k => k.trim());

        // Filtrar campos para el DO UPDATE SET (excluimos URLs, fechas estáticas y las columnas que componen la PK)
        const updateParts = insertFields
            .filter(f => f !== 'url' && f !== 'created_at' && !pkList.includes(f))
            .map(f => `${f} = EXCLUDED.${f}`);

        if (updateParts.length > 0) {
            query = `INSERT INTO ${table} (${insertFields.join(', ')}) VALUES (${placeholders.join(', ')}) ON CONFLICT (${primaryKeyStr}) DO UPDATE SET ${updateParts.join(', ')} RETURNING *;`;
        } else {
            query = `INSERT INTO ${table} (${insertFields.join(', ')}) VALUES (${placeholders.join(', ')}) ON CONFLICT (${primaryKeyStr}) DO NOTHING RETURNING *;`;
        }
        break;
    }
    case 'update': {
        const primaryKeyStr = config.primary_key || 'id';
        const pkList = primaryKeyStr.split(',').map(k => k.trim());

        const updateParts = [];
        let paramIndex = 1;

        // Construir los asignamientos SET excluyendo los campos de la PK
        Object.entries(fields).forEach(([key, value]) => {
            if ((config.allowed_fields || []).includes(key) && !pkList.includes(key)) {
                if (key === 'password' && (!value || value === '')) return; 
                updateParts.push(`${key} = $${paramIndex++}`);
                values.push(processValue(key, value));
            }
        });

        if (updateParts.length === 0) throw new Error("No hay campos válidos para actualizar.");

        // Construir la cláusula WHERE evaluando todas las columnas de la PK
        const whereParts = [];
        pkList.forEach(pkField => {
            const idVal = body[pkField] ?? fields[pkField];
            if (idVal === undefined || idVal === null) {
                throw new Error(`UPDATE requiere el valor de la llave primaria (${pkField}).`);
            }
            whereParts.push(`${pkField} = $${paramIndex++}`);
            values.push(idVal);
        });

        query = `UPDATE ${table} SET ${updateParts.join(', ')} WHERE ${whereParts.join(' AND ')} RETURNING *;`;
        break;
    }
    case 'getall': {
        const { limit, offset } = sanitizePaginationParams(body.limit, body.offset);

        let selectFields = buildSelectFields();
        // 🚀 HOTFIX ARQUITECTÓNICO 1: Sobrescribir el Rol global con el Rol del Tenant
        if (table === 'users') {
            selectFields = selectFields.replace(`${table}.*`, `${table}.*, uc.role`);
        }

        let baseQuery = `SELECT ${selectFields} FROM ${table} ${buildJoins()}`;
        let whereParts = [];
        let paramIndex = 1;

        // 🚀 HOTFIX ARQUITECTÓNICO 2: Inyectar JOIN con tabla pivote para Multi-Tenancy
        if (table === 'users') {
            if (!baseQuery.includes('user_companies')) {
                baseQuery += ` INNER JOIN user_companies uc ON ${table}.email = uc.email`;
            }
        }

        Object.entries(fields).forEach(([key, value]) => {
            const isAllowed = (config.allowed_fields || []).includes(key);

            if (isAllowed && key !== 'limit' && key !== 'offset') {
                let dbColumn = `${table}.${key}`;

                // Redirección del filtro hacia la tabla pivote
                if (table === 'users' && key === 'tenant_id') {
                    dbColumn = 'uc.id_company';
                } else if (key === 'created_at' || key === 'check_in') {
                    dbColumn = `(${table}.${key} - INTERVAL '6 hours')::date`;
                }

                if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
                    Object.entries(value).forEach(([op, val]) => {
                        const sqlOp = op === '_gte' ? '>=' : op === '_lte' ? '<=' : op === '_gt' ? '>' : op === '_lt' ? '<' : '=';
                        const isDateLike = typeof val === 'string' && (val.includes('T') || /^\d{4}-\d{2}-\d{2}$/.test(val));

                        // 🛡️ PATCH 1: Evita que basura intente evaluarse como fecha en un objeto
                        if ((key === 'created_at' || key === 'check_in' || key === 'check_out') && !isDateLike) return;

                        if (isDateLike && key !== 'created_at' && key !== 'check_in') {
                             whereParts.push(`${dbColumn}::date ${sqlOp} $${paramIndex++}::date`);
                             values.push(val.split('T')[0]);
                        } else {
                             whereParts.push(`${dbColumn} ${sqlOp} $${paramIndex++}`);
                             values.push(val);
                        }
                    });
                } else if (value !== undefined && value !== '' && value !== null) {
                    const isDateLike = typeof value === 'string' && (value.includes('T') || /^\d{4}-\d{2}-\d{2}$/.test(value));

                    // 🛡️ PATCH 2: Evita el colapso de Postgres si el frontend manda texto en campos de fecha
                    if ((key === 'created_at' || key === 'check_in' || key === 'check_out') && !isDateLike) return;

                    if (isDateLike && key !== 'created_at' && key !== 'check_in') {
                        whereParts.push(`${dbColumn}::date = $${paramIndex++}::date`);
                        values.push(value.split('T')[0]);
                    } else {
                        whereParts.push(`${dbColumn} = $${paramIndex++}`);
                        values.push(value);
                    }
                } else if (value === null) {
                    whereParts.push(`${dbColumn} IS NULL`);
                }
            }
        });

        // 🛡️ FIX: Resolver la Ambigüedad de la columna is_active en el default_filter
        if (config.default_filter && !fields.hasOwnProperty('is_active') && !config.default_filter.includes('$1')) {
            let defFilter = config.default_filter;
            if (table === 'users' && defFilter.includes('is_active')) {
                defFilter = defFilter.replace('is_active', `${table}.is_active`);
            }
            whereParts.push(defFilter);
        }

        if (whereParts.length > 0) baseQuery += ` WHERE ${whereParts.join(' AND ')}`;

        let sortCol = body.sort_by ? body.sort_by : (fields.published_at ? 'published_at' : 'created_at');
        let finalSortCol = (table === 'users' && sortCol === 'tenant_id') ? 'uc.id_company' : `${table}.${sortCol}`;

        baseQuery += ` ORDER BY ${finalSortCol} DESC NULLS LAST LIMIT $${paramIndex++} OFFSET $${paramIndex++};`;

        query = baseQuery;
        values.push(limit, offset);
        break;
    }
    case 'delete': {
        const pkField = config.primary_key || 'id';
        const idValue = body[pkField] || fields[pkField] || body.id || fields.id;
        if (!idValue) throw new Error(`DELETE requiere el valor de ${pkField}`);
        query = `UPDATE ${table} SET is_active = false WHERE ${pkField} = $1 RETURNING *;`;
        values = [idValue];
        break;
    }
    case 'getone': {
        const pkField = config.primary_key || 'id';
        let val = fields[pkField] || body[pkField] || body.id || fields.id || fields.email || body.email;
        if (!val && Object.keys(fields).length > 0) {
            const firstKey = Object.keys(fields)[0];
            val = fields[firstKey];
            query = `SELECT ${buildSelectFields()} FROM ${table} ${buildJoins()} WHERE ${table}.${firstKey} = $1 LIMIT 1;`;
        } else if (val) {
            const searchField = (fields.email || body.email) && !fields[pkField] ? 'email' : pkField;
            query = `SELECT ${buildSelectFields()} FROM ${table} ${buildJoins()} WHERE ${table}.${searchField} = $1 LIMIT 1;`;
        }
        if (!val) throw new Error(`GETONE requiere un ID o un campo de búsqueda.`);
        values = [val];
        break;
    }
    case 'call_sp': {
	    // Whitelist explícito: solo esta función es invocable, para no abrir RCE a cualquier SP
	    const allowedFunctions = { 'sp_procesar_salida_ganado': ['electronic_rfid'] };
	    const fnName = config.table_name; 
	    if (!allowedFunctions[fnName]) throw new Error(`Función no permitida: ${fnName}`);
	    query = `SELECT ${fnName}($1) AS resultado;`;
	    values = [fields[allowedFunctions[fnName][0]]];
	    break;
	}

}

return [{ json: { query, values, operation, is_transactional: ['insert', 'update', 'delete'].includes(operation) } }];

// Recuperamos los datos ejecutados
const sqlResults = $input.all().map(item => item.json); 
const config = $('Security Validation').first().json;
const operation = config.operation.toLowerCase();

// Validamos si Postgres tiró error (continueOnFail)
if (sqlResults.length > 0 && sqlResults[0].error) {
    return [{
        json: {
            error: true,
            operation,
            message: sqlResults[0].message || "Error al ejecutar consulta en base de datos",
            data: null
        }
    }];
}

// Filtramos filas reales (evitamos metadatos vacíos si los hay)
const rows = sqlResults.filter(row => row && typeof row === 'object' && !row.hasOwnProperty('success'));

let data = rows;
let resultStatus = "success";
let message = "Ejecución satisfactoria";
let foundRecords = rows.length;

// Lógica de Normalización
switch (operation) {
  case 'getone':
    if (rows.length === 0) {
      data = null; resultStatus = "error"; message = "Registro no encontrado."; foundRecords = 0;
    } else {
      data = rows[0]; foundRecords = 1;
    }
    break;
  case 'update':
    if (rows.length === 0) {
      data = []; resultStatus = "error"; message = "No se actualizó ningún registro. Verifica el ID."; foundRecords = 0;
    }
    break;
  case 'delete':
    if (rows.length === 0) {
      data = []; resultStatus = "error"; message = "No se pudo eliminar. El registro no existe."; foundRecords = 0;
    } else {
      message = "Registro eliminado con éxito.";
    }
    break;
  case 'getall':
    data = rows; foundRecords = rows.length;
    break;
  case 'insert':
    data = rows[0] || rows; foundRecords = rows.length;
    break;
  case 'call_sp':
    data = rows[0]?.resultado ?? null;
    foundRecords = data ? 1 : 0;
    break;
}

const postHooks = (resultStatus === "success" && config.hooks?.post) ? config.hooks.post : [];

return [{
  json: {
    error: resultStatus !== "success",
    operation,
    message,
    data,
    execution_info: {
      timestamp: new Date().toISOString(),
      model: config.model_name,
      has_post_hooks: postHooks.length > 0
    }
  }
}];
